arguments.file_text:
:root {
  --bg: #0b0c10;
  --bg-elev: #14161d;
  --bg-elev-2: #1c1f29;
  --surface: #1a1d26;
  --border: #2a2f3d;
  --border-strong: #3a4154;
  --text: #f3f4f8;
  --text-muted: #b6bccd;
  --text-dim: #8a91a6;
  --accent: #ffb454;
  --accent-strong: #ffc777;
  --accent-ink: #1a1200;
  --danger: #ff7a7a;
  --success: #7ee0a8;
  --focus: #9ecbff;
  --radius: 12px;
  --radius-lg: 18px;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
  --container: 1240px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a {
  color: var(--text);
  text-decoration: none;
}
a:hover { color: var(--accent-strong); }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

button {
  font: inherit;
  cursor: pointer;
  background: none;
  border: none;
  color: inherit;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  border-radius: 8px;
  font-weight: 600;
  z-index: 1000;
  transition: top 0.15s ease;
}
.skip-link:focus { top: 12px; }

/* Layout */
.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* Top bar */
.topbar {
  background: #07080c;
  border-bottom: 1px solid var(--border);
  font-size: 0.85rem;
  color: var(--text-muted);
}
.topbar-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 24px;
  max-width: var(--container);
  margin: 0 auto;
  gap: 16px;
  flex-wrap: wrap;
}
.topbar-inner ul {
  display: flex;
  gap: 18px;
  list-style: none;
  margin: 0; padding: 0;
}
.topbar a:hover { color: var(--accent-strong); }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 12, 16, 0.92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 14px 0;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: 0.02em;
}
.brand-mark {
  width: 32px; height: 32px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #ff7a59);
  display: grid; place-items: center;
  color: var(--accent-ink);
  font-weight: 900;
}

.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 8px;
  margin: 0; padding: 0;
  justify-content: center;
}
.primary-nav a {
  padding: 8px 14px;
  border-radius: 8px;
  color: var(--text-muted);
  font-weight: 500;
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  width: 40px; height: 40px;
  border-radius: 10px;
  display: grid; place-items: center;
  color: var(--text-muted);
  position: relative;
  border: 1px solid transparent;
}
.icon-btn:hover {
  background: var(--bg-elev);
  color: var(--text);
  border-color: var(--border);
}
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 700;
  border-radius: 10px;
  padding: 1px 6px;
  min-width: 18px;
  text-align: center;
  line-height: 1.4;
}

/* Search */
.search-form {
  display: flex;
  align-items: center;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 4px 4px 4px 12px;
  min-width: 220px;
  max-width: 320px;
}
.search-form:focus-within {
  border-color: var(--focus);
  outline: 2px solid var(--focus);
  outline-offset: 1px;
}
.search-form input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text);
  padding: 6px 8px;
  font: inherit;
  min-width: 0;
}
.search-form input:focus { outline: none; }
.search-form input::placeholder { color: var(--text-dim); }
.search-form button {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  padding: 6px 12px;
  font-weight: 600;
}
.search-form button:hover { background: var(--accent-strong); }

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* Hero */
.hero {
  position: relative;
  margin-top: 28px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background:
    radial-gradient(1100px 500px at 80% 20%, rgba(255, 180, 84, 0.18), transparent 60%),
    radial-gradient(700px 400px at 10% 90%, rgba(126, 224, 168, 0.12), transparent 60%),
    linear-gradient(180deg, #11141d, #0d0f15);
  border: 1px solid var(--border);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 32px;
  align-items: center;
  padding: 56px 48px;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-strong);
  background: rgba(255, 180, 84, 0.1);
  border: 1px solid rgba(255, 180, 84, 0.3);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 18px;
}
.hero h1 {
  font-size: clamp(2rem, 4vw, 3.4rem);
  line-height: 1.1;
  margin: 0 0 16px;
  letter-spacing: -0.02em;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(90deg, var(--accent), #ff7a59);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p {
  color: var(--text-muted);
  font-size: 1.1rem;
  max-width: 52ch;
  margin: 0 0 28px;
}
.hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 10px;
  font-weight: 600;
  border: 1px solid transparent;
  transition: transform 0.05s ease, background 0.15s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-strong); color: var(--accent-ink); }
.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-elev); }

.hero-visual {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, #2b2233 0%, #0e1419 100%);
  overflow: hidden;
  border: 1px solid var(--border);
}
.hero-visual::before {
  content: "";
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 30% 30%, rgba(255, 180, 84, 0.4), transparent 50%),
    radial-gradient(circle at 70% 80%, rgba(126, 138, 224, 0.35), transparent 55%);
}
.hero-product {
  position: absolute;
  inset: 12%;
  background: linear-gradient(180deg, #f0eadf, #c8b89a);
  border-radius: 50% 50% 12% 12% / 35% 35% 12% 12%;
  box-shadow: inset 0 -40px 80px rgba(0,0,0,0.25), 0 30px 60px rgba(0,0,0,0.5);
}
.hero-tag {
  position: absolute;
  background: rgba(20, 22, 29, 0.85);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 14px;
  font-size: 0.85rem;
  backdrop-filter: blur(6px);
}
.hero-tag.tl { top: 18px; left: 18px; }
.hero-tag.br { bottom: 18px; right: 18px; }
.hero-tag strong { display: block; color: var(--accent-strong); font-size: 1rem; }

/* Section */
section.block {
  margin-top: 64px;
}
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-size: clamp(1.4rem, 2.4vw, 2rem);
  margin: 0;
  letter-spacing: -0.01em;
}
.section-head p {
  color: var(--text-muted);
  margin: 6px 0 0;
}
.section-link {
  color: var(--accent-strong);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.section-link:hover { color: var(--accent); }

/* Category strip */
.categories {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  text-align: center;
  color: var(--text);
  transition: border-color 0.15s, transform 0.15s;
}
.category-card:hover {
  border-color: var(--border-strong);
  transform: translateY(-2px);
  color: var(--text);
}
.category-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #232838, #161922);
  display: grid; place-items: center;
  color: var(--accent-strong);
  border: 1px solid var(--border);
}
.category-card span { font-weight: 500; font-size: 0.95rem; }

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.15s, transform 0.15s;
  position: relative;
}
.product-card:hover {
  border-color: var(--border-strong);
  transform: translateY(-2px);
}
.product-media {
  aspect-ratio: 1/1;
  position: relative;
  background: linear-gradient(135deg, #20242f, #11141b);
  overflow: hidden;
}
.product-media .swatch {
  position: absolute;
  inset: 14%;
  border-radius: 16px;
  box-shadow: inset 0 -30px 60px rgba(0,0,0,0.3), 0 14px 30px rgba(0,0,0,0.4);
}
.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 6px;
}
.product-badge.new { background: #7ee0a8; }
.product-badge.sale { background: #ff7a7a; color: #2b0808; }

.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(11, 12, 16, 0.7);
  border: 1px solid var(--border);
  color: var(--text-muted);
  display: grid; place-items: center;
  backdrop-filter: blur(6px);
}
.wishlist-btn:hover { color: var(--accent); }
.wishlist-btn[aria-pressed="true"] {
  color: var(--accent);
  background: rgba(255, 180, 84, 0.15);
  border-color: var(--accent);
}

.product-info {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-dim);
}
.product-name {
  font-weight: 600;
  font-size: 1rem;
  margin: 0;
  color: var(--text);
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  color: var(--text-muted);
}
.stars {
  color: var(--accent-strong);
  letter-spacing: 1px;
}
.product-price {
  margin-top: auto;
  padding-top: 8px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.price-now {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text);
}
.price-was {
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.9rem;
}
.price-save {
  font-size: 0.78rem;
  color: var(--success);
  font-weight: 600;
}
.add-cart {
  margin: 0 16px 16px;
  padding: 10px;
  border-radius: 8px;
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--border);
  font-weight: 600;
  text-align: center;
}
.add-cart:hover {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* Deals */
.deals {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 20px;
}
.deal-feature {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background:
    radial-gradient(800px 400px at 80% 20%, rgba(255, 122, 89, 0.25), transparent 60%),
    linear-gradient(135deg, #2a1c1c, #0e1015);
  border: 1px solid var(--border);
  padding: 36px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 360px;
}
.countdown-label {
  color: var(--text-muted);
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.countdown {
  display: flex;
  gap: 12px;
}
.countdown-cell {
  background: rgba(11, 12, 16, 0.6);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 14px;
  text-align: center;
  min-width: 64px;
}
.countdown-cell strong {
  display: block;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}
.countdown-cell span {
  font-size: 0.7rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.deal-feature h3 {
  font-size: clamp(1.6rem, 2.4vw, 2.2rem);
  margin: 16px 0 8px;
  letter-spacing: -0.01em;
}
.deal-feature p {
  color: var(--text-muted);
  margin: 0 0 20px;
  max-width: 50ch;
}
.deal-side {
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--surface);
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  min-height: 170px;
}
.deal-card.purple {
  background: radial-gradient(500px 220px at 100% 0%, rgba(126, 138, 224, 0.3), transparent 60%), var(--surface);
}
.deal-card.green {
  background: radial-gradient(500px 220px at 0% 100%, rgba(126, 224, 168, 0.18), transparent 60%), var(--surface);
}
.deal-card .small-eyebrow {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-strong);
  margin-bottom: 6px;
}
.deal-card h4 {
  font-size: 1.25rem;
  margin: 0 0 6px;
}
.deal-card p {
  color: var(--text-muted);
  margin: 0;
  font-size: 0.95rem;
}
.deal-card a.shop-link {
  margin-top: 14px;
  color: var(--accent-strong);
  font-weight: 600;
  font-size: 0.9rem;
}

/* Editorial */
.editorial {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.article-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.article-card:hover { border-color: var(--border-strong); }
.article-media {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #2b2438, #11141b);
  position: relative;
}
.article-media.a { background: linear-gradient(135deg, #3b2745, #11141b); }
.article-media.b { background: linear-gradient(135deg, #1f3340, #0c1116); }
.article-media.c { background: linear-gradient(135deg, #3b2e1c, #0c0f14); }
.article-media::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(400px 200px at 30% 30%, rgba(255,255,255,0.08), transparent 60%);
}
.article-tag {
  position: absolute;
  top: 14px; left: 14px;
  background: rgba(11, 12, 16, 0.75);
  color: var(--accent-strong);
  border: 1px solid var(--border);
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  z-index: 1;
}
.article-body {
  padding: 18px 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.article-meta {
  font-size: 0.8rem;
  color: var(--text-dim);
}
.article-body h3 {
  font-size: 1.15rem;
  margin: 0;
  line-height: 1.35;
}
.article-body h3 a:hover { color: var(--accent-strong); }
.article-body p {
  color: var(--text-muted);
  margin: 0;
  font-size: 0.95rem;
}

/* Newsletter */
.newsletter {
  margin-top: 64px;
  background:
    radial-gradient(700px 300px at 90% 50%, rgba(255, 180, 84, 0.18), transparent 60%),
    linear-gradient(135deg, #161a23, #0d1016);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 44px;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 32px;
  align-items: center;
}
.newsletter h2 {
  font-size: clamp(1.4rem, 2.2vw, 1.9rem);
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}
.newsletter p {
  color: var(--text-muted);
  margin: 0;
}
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.newsletter-row {
  display: flex;
  gap: 8px;
}
.newsletter-row input {
  flex: 1;
  padding: 14px 16px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text);
  font: inherit;
  min-width: 0;
}
.newsletter-row input:focus {
  outline: 2px solid var(--focus);
  border-color: var(--focus);
}
.newsletter-row input[aria-invalid="true"] {
  border-color: var(--danger);
}
.newsletter .help {
  font-size: 0.85rem;
  color: var(--text-dim);
}
.newsletter .error {
  font-size: 0.85rem;
  color: var(--danger);
}
.newsletter .success {
  font-size: 0.9rem;
  color: var(--success);
  font-weight: 600;
}

/* Footer */
.site-footer {
  margin-top: 80px;
  border-top: 1px solid var(--border);
  background: #07080c;
  padding: 48px 0 24px;
  color: var(--text-muted);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 32px;
}
.footer-grid h3 {
  color: var(--text);
  font-size: 0.95rem;
  margin: 0 0 14px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.footer-grid ul {
  list-style: none;
  padding: 0; margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.footer-grid a { color: var(--text-muted); }
.footer-grid a:hover { color: var(--accent-strong); }
.footer-brand p { max-width: 32ch; }
.socials {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}
.socials a {
  width: 36px; height: 36px;
  border-radius: 8px;
  border: 1px solid var(--border);
  display: grid; place-items: center;
  color: var(--text-muted);
}
.socials a:hover { color: var(--accent); border-color: var(--accent); }

.footer-bottom {
  margin-top: 36px;
  padding-top: 20px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 0.85rem;
  color: var(--text-dim);
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial { grid-template-columns: repeat(2, 1fr); }
  .categories { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .deals { grid-template-columns: 1fr; }
  .deal-side { grid-template-rows: auto; grid-template-columns: 1fr 1fr; }
  .hero-inner { grid-template-columns: 1fr; padding: 40px 28px; }
  .newsletter { grid-template-columns: 1fr; padding: 32px; }
}

@media (max-width: 720px) {
  .topbar { display: none; }
  .menu-toggle {
    display: grid;
    place-items: center;
    width: 40px; height: 40px;
    border-radius: 10px;
    color: var(--text);
    border: 1px solid var(--border);
  }
  .header-inner {
    grid-template-columns: auto 1fr auto;
  }
  .primary-nav {
    display: none;
    grid-column: 1 / -1;
    padding: 8px 0 12px;
  }
  .primary-nav.open { display: block; }
  .primary-nav ul {
    flex-direction: column;
    gap: 4px;
    align-items: stretch;
  }
  .primary-nav a { display: block; }
  .search-form { display: none; }
  .header-inner.search-open .search-form {
    display: flex;
    grid-column: 1 / -1;
    max-width: none;
  }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .editorial { grid-template-columns: 1fr; }
  .categories { grid-template-columns: repeat(2, 1fr); }
  .deal-side { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .hero-inner { padding: 32px 20px; }
  .deal-feature { padding: 28px 22px; }
  .newsletter-row { flex-direction: column; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .add-cart, .icon-btn, .category-card, .product-card,
  .article-card, .deal-card, .deal-feature, .hero, .newsletter,
  .countdown-cell, .search-form, .newsletter-row input {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .add-cart:hover, .search-form button {
    background: ButtonText; color: ButtonFace;
  }
  .product-badge, .article-tag { border: 1px solid ButtonBorder; }
  :focus-visible { outline: 3px solid Highlight; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

