    fill: "none", stroke: "currentColor", strokeWidth: 1.8,
    strokeLinecap: "round", strokeLinejoin: "round",
    "aria-hidden": "true", focusable: "false"
  };
  const paths = {
    search: <><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></>,
    user: <><circle cx="12" cy="8" r="4" /><path d="M4 21a8 8 0 0 1 16 0" /></>,
    heart: <path d="M12 21s-7-4.35-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.65-9.5 9-9.5 9Z" />,
    bag: <><path d="M5 8h14l-1 12a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 8Z" /><path d="M9 8a3 3 0 0 1 6 0" /></>,
    arrow: <><path d="M5 12h14" /><path d="m13 6 6 6-6 6" /></>,
    menu: <><path d="M4 6h16"/><path d="M4 12h16"/><path d="M4 18h16"/></>,
    close: <><path d="M6 6l12 12"/><path d="M18 6 6 18"/></>,
    truck: <><path d="M3 7h11v9H3z"/><path d="M14 10h4l3 3v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/></>,
    shield: <path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6l-8-3Z"/>,
    refresh: <><path d="M21 12a9 9 0 1 1-3-6.7"/><path d="M21 4v5h-5"/></>,
    sparkle: <><path d="M12 3v4"/><path d="M12 17v4"/><path d="M3 12h4"/><path d="M17 12h4"/><path d="m6 6 2.5 2.5"/><path d="m15.5 15.5 2.5 2.5"/><path d="m6 18 2.5-2.5"/><path d="m15.5 8.5 2.5-2.5"/></>,
    shirt: <path d="M4 7l4-3 4 2 4-2 4 3-2 3-2-1v11H8V9L6 10 4 7Z"/>,
    shoe: <path d="M3 16h12l4-2 2 2v3H3v-3Z M3 16c0-3 2-5 5-5l3 3"/>,
    bag2: <><path d="M6 7h12v13H6z"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/></>,
    watch: <><circle cx="12" cy="12" r="5"/><path d="M9 7V4h6v3"/><path d="M9 17v3h6v-3"/></>,
    glasses: <><circle cx="6" cy="14" r="3"/><circle cx="18" cy="14" r="3"/><path d="M9 14h6"/></>,
    home: <><path d="M3 11l9-7 9 7"/><path d="M5 10v10h14V10"/></>,
    twitter: <path d="M22 5.8c-.7.3-1.5.6-2.3.7.8-.5 1.5-1.3 1.8-2.2-.8.5-1.7.8-2.6 1A4.1 4.1 0 0 0 12 9.3c0 .3 0 .6.1.9C8.7 10 5.7 8.4 3.7 5.9c-.4.6-.6 1.4-.6 2.1 0 1.5.7 2.7 1.8 3.5-.7 0-1.3-.2-1.9-.5 0 2 1.4 3.7 3.3 4.1-.3.1-.7.1-1.1.1-.3 0-.5 0-.8-.1.5 1.7 2.1 2.9 3.9 2.9-1.4 1.1-3.2 1.8-5.2 1.8H2c1.8 1.2 4 1.8 6.3 1.8 7.5 0 11.6-6.3 11.6-11.7v-.5c.8-.5 1.5-1.2 2.1-2Z"/>,
    instagram: <><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="0.8" fill="currentColor"/></>,
    youtube: <><rect x="2" y="5" width="20" height="14" rx="3"/><path d="m10 9 5 3-5 3V9Z" fill="currentColor"/></>,
    tiktok: <path d="M14 4v9.5a3.5 3.5 0 1 1-3.5-3.5"/>
  };
  return <svg {...common}>{paths[name]}</svg>;
};

// ---------- Data ----------
const CATEGORIES = [
  { name: "Apparel", icon: "shirt" },
  { name: "Footwear", icon: "shoe" },
  { name: "Bags", icon: "bag2" },
  { name: "Watches", icon: "watch" },
  { name: "Eyewear", icon: "glasses" },
  { name: "Home", icon: "home" }
];

const PRODUCTS = [
  { id: 1, name: "Atlas Wool Overcoat", category: "Outerwear", price: 248, was: 320, rating: 4.8, reviews: 142, swatch: "linear-gradient(135deg,#3a4255,#1c1f2a)", badge: "sale" },
  { id: 2, name: "Cloudfoam Runner '24", category: "Footwear", price: 139, rating: 4.6, reviews: 98, swatch: "linear-gradient(135deg,#e6e7ec,#9ea3b3)", badge: "new" },
  { id: 3, name: "Ridge Leather Tote", category: "Bags", price: 184, was: 220, rating: 4.9, reviews: 76, swatch: "linear-gradient(135deg,#7a4a2a,#3b2412)", badge: "sale" },
  { id: 4, name: "Meridian Auto Watch", category: "Accessories", price: 412, rating: 4.7, reviews: 54, swatch: "linear-gradient(135deg,#cfd3dc,#5a6072)" },
  { id: 5, name: "Linen Field Shirt", category: "Apparel", price: 88, rating: 4.5, reviews: 211, swatch: "linear-gradient(135deg,#d8c9a8,#7a6a4c)", badge: "new" },
  { id: 6, name: "Voyager Aviator Frames", category: "Eyewear", price: 156, rating: 4.6, reviews: 63, swatch: "linear-gradient(135deg,#222629,#0a0c0e)" },
  { id: 7, name: "Quilted Travel Jacket", category: "Outerwear", price: 196, was: 245, rating: 4.4, reviews: 87, swatch: "linear-gradient(135deg,#2a4a3a,#102018)", badge: "sale" },
  { id: 8, name: "Heritage Suede Boot", category: "Footwear", price: 219, rating: 4.7, reviews: 132, swatch: "linear-gradient(135deg,#8a6240,#3a2614)" }
];

const ARTICLES = [
  { id: 1, tag: "Style Guide", title: "Layering for shoulder season: a 5-piece capsule", excerpt: "Versatile pieces that take you from breezy mornings to crisp evenings without missing a beat.", meta: "Editorial · 6 min read", media: "a" },
  { id: 2, tag: "Behind the Brand", title: "Inside the Ridge atelier: how our leather is made", excerpt: "A visit to the family-run tannery that has supplied our workshop for over two decades.", meta: "Stories · 8 min read", media: "b" },
  { id: 3, tag: "Sustainability", title: "Our 2026 commitment: lower-impact materials", excerpt: "We're tracing every fiber. Here's what we've changed and the road still ahead.", meta: "Impact · 4 min read", media: "c" }
];

// ---------- Components ----------
const TopBar = () => (
  <div className="topbar" role="region" aria-label="Promotional and helpful links">
    <div className="topbar-inner">
      <p style={{ margin: 0 }}>Free carbon-neutral shipping over $75 · 60-day returns</p>
      <ul>
        <li><a href="#track">Track order</a></li>
        <li><a href="#stores">Stores</a></li>
        <li><a href="#help">Help</a></li>
      </ul>
    </div>
  </div>
);

const Header = ({ cartCount, wishlistCount }) => {
  const [menuOpen, setMenuOpen] = useState(false);
  return (
    <header className="site-header">
      <div className="container">
        <div className={"header-inner" + (menuOpen ? " menu-open" : "")}>
          <a href="#" className="brand" aria-label="Northform home">
            <span className="brand-mark" aria-hidden="true">N</span>
            <span>Northform</span>
          </a>

          <nav className={"primary-nav" + (menuOpen ? " open" : "")} aria-label="Primary">
            <ul>
              <li><a href="#new" aria-current="page">New</a></li>
              <li><a href="#men">Men</a></li>
              <li><a href="#women">Women</a></li>
              <li><a href="#accessories">Accessories</a></li>
              <li><a href="#sale">Sale</a></li>
              <li><a href="#journal">Journal</a></li>
            </ul>
          </nav>

          <div className="header-actions">
            <form className="search-form" role="search" onSubmit={(e) => e.preventDefault()}>
              <label htmlFor="site-search" className="visually-hidden" style={{ position: "absolute", left: -9999 }}>Search products</label>
              <Icon name="search" size={18} />
              <input id="site-search" type="search" placeholder="Search products" />
              <button type="submit">Search</button>
            </form>
            <button className="icon-btn" aria-label="Account">
              <Icon name="user" />
            </button>
            <a href="#wishlist" className="icon-btn" aria-label={`Wishlist, ${wishlistCount} items`}>
              <Icon name="heart" />
              {wishlistCount > 0 && <span className="badge" aria-hidden="true">{wishlistCount}</span>}
            </a>
            <a href="#cart" className="icon-btn" aria-label={`Cart, ${cartCount} items`}>
              <Icon name="bag" />
              {cartCount > 0 && <span className="badge" aria-hidden="true">{cartCount}</span>}
            </a>
            <button
              className="menu-toggle"
              aria-expanded={menuOpen}
              aria-controls="primary-nav"
              aria-label="Toggle menu"
              onClick={() => setMenuOpen(o => !o)}
            >
              <Icon name={menuOpen ? "close" : "menu"} />
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};

const Hero = () => (
  <section className="hero" aria-labelledby="hero-heading">
    <div className="hero-inner">
      <div>
        <span className="hero-eyebrow"><Icon name="sparkle" size={14}/> Fall 2026 collection</span>
        <h1 id="hero-heading">
          Built for the in-between. <em>Designed to last.</em>
        </h1>
        <p>
          Considered essentials in natural fibers and recycled metals — engineered
          for everyday wear and made to be repaired, not replaced.
        </p>
        <div className="hero-cta">
          <a href="#shop" className="btn btn-primary">Shop the collection <Icon name="arrow" size={16}/></a>
          <a href="#story" className="btn btn-secondary">Our story</a>
        </div>
      </div>
      <div className="hero-visual" aria-hidden="true">
        <div className="hero-product"></div>
        <div className="hero-tag tl"><strong>Ridge Tote</strong>Vegetable-tanned</div>
        <div className="hero-tag br"><strong>$184</strong>Save $36</div>
      </div>
    </div>
  </section>
);

const ValueProps = () => {
  const items = [
    { icon: "truck", title: "Free shipping over $75" },
    { icon: "refresh", title: "60-day easy returns" },
    { icon: "shield", title: "2-year repair guarantee" },
    { icon: "sparkle", title: "Members earn 5% back" }
  ];
  return (
    <section className="block" aria-label="Shop benefits">
      <ul className="categories" style={{ gridTemplateColumns: "repeat(4, 1fr)" }}>
        {items.map(it => (
          <li key={it.title} style={{ listStyle: "none" }}>
            <div className="category-card" style={{ flexDirection: "row", justifyContent: "flex-start", textAlign: "left", gap: 14 }}>
              <span className="category-icon"><Icon name={it.icon} /></span>
              <span>{it.title}</span>
            </div>
          </li>
        ))}
      </ul>
    </section>
  );
};

const Categories = () => (
  <section className="block" aria-labelledby="cat-head">
    <div className="section-head">
      <div>
        <h2 id="cat-head">Shop by category</h2>
        <p>Find what you're looking for, faster.</p>
      </div>
      <a href="#all" className="section-link">View all <Icon name="arrow" size={14}/></a>
    </div>
    <ul className="categories" style={{ padding: 0, margin: 0 }}>
      {CATEGORIES.map(c => (
        <li key={c.name} style={{ listStyle: "none" }}>
          <a href={"#" + c.name.toLowerCase()} className="category-card">
            <span className="category-icon" aria-hidden="true"><Icon name={c.icon} /></span>
            <span>{c.name}</span>
          </a>
        </li>
      ))}
    </ul>
  </section>
);

const Stars = ({ rating }) => {
  const full = Math.round(rating);
  return (
    <span className="stars" aria-hidden="true">
      {"★★★★★".slice(0, full)}<span style={{ color: "var(--text-dim)" }}>{"☆☆☆☆☆".slice(0, 5 - full)}</span>
    </span>
  );
};

const ProductCard = ({ product, onWishlist, onAdd, wishlisted }) => {
  const save = product.was ? Math.round(((product.was - product.price) / product.was) * 100) : 0;
  return (
    <article className="product-card" aria-labelledby={`p-${product.id}-name`}>
      <div className="product-media">
        <div className="swatch" style={{ background: product.swatch }} aria-hidden="true"></div>
        {product.badge === "sale" && <span className="product-badge sale">Sale</span>}
        {product.badge === "new" && <span className="product-badge new">New</span>}
        <button
          className="wishlist-btn"
          aria-pressed={wishlisted}
          aria-label={`${wishlisted ? "Remove from" : "Add to"} wishlist: ${product.name}`}
          onClick={() => onWishlist(product.id)}
        >
          <Icon name="heart" size={18} />
        </button>
      </div>
      <div className="product-info">
        <span className="product-cat">{product.category}</span>
        <h3 id={`p-${product.id}-name`} className="product-name">
          <a href={`#product-${product.id}`}>{product.name}</a>
        </h3>
        <div className="product-rating">
          <Stars rating={product.rating} />
          <span>{product.rating.toFixed(1)} ({product.reviews})</span>
        </div>
        <div className="product-price">
          <span className="price-now">${product.price}</span>
          {product.was && <span className="price-was" aria-label={`Original price $${product.was}`}>${product.was}</span>}
          {save > 0 && <span className="price-save">-{save}%</span>}
        </div>
      </div>
      <button className="add-cart" onClick={() => onAdd(product.id)} aria-label={`Add to cart: ${product.name}`}>
        Add to cart
      </button>
    </article>
  );
};

const FeaturedProducts = ({ wishlist, onWishlist, onAdd }) => (
  <section className="block" aria-labelledby="featured-head">
    <div className="section-head">
      <div>
        <h2 id="featured-head">Featured this week</h2>
        <p>Hand-picked by our team. Limited stock.</p>
      </div>
      <a href="#shop" className="section-link">Shop all <Icon name="arrow" size={14}/></a>
    </div>
    <div className="product-grid">
      {PRODUCTS.map(p => (
        <ProductCard
          key={p.id}
          product={p}
          wishlisted={wishlist.has(p.id)}
          onWishlist={onWishlist}
          onAdd={onAdd}
        />
      ))}
    </div>
  </section>
);

const Countdown = () => {
  const target = useMemo(() => Date.now() + (1000 * 60 * 60 * 36), []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  let diff = Math.max(0, target - now);
  const h = Math.floor(diff / 3600000); diff -= h * 3600000;
  const m = Math.floor(diff / 60000);   diff -= m * 60000;
  const s = Math.floor(diff / 1000);
  const pad = (n) => n.toString().padStart(2, "0");
  return (
    <div className="countdown" role="timer" aria-live="off" aria-label={`${h} hours, ${m} minutes, ${s} seconds remaining`}>
      <div className="countdown-cell"><strong>{pad(h)}</strong><span>Hours</span></div>
      <div className="countdown-cell"><strong>{pad(m)}</strong><span>Mins</span></div>
      <div className="countdown-cell"><strong>{pad(s)}</strong><span>Secs</span></div>
    </div>
  );
};

const Deals = () => (
  <section className="block" aria-labelledby="deals-head">
    <div className="section-head">
      <div>
        <h2 id="deals-head">Deals & drops</h2>
        <p>Limited offers and member-only pricing.</p>
      </div>
    </div>
    <div className="deals">
      <article className="deal-feature" aria-labelledby="flash-title">
        <div>
          <p className="countdown-label">Flash sale ends in</p>
          <Countdown />
        </div>
        <div>
          <h3 id="flash-title">Up to 40% off outerwear</h3>
          <p>Insulated, weatherproof, and built for the long haul. Only while stock lasts.</p>
          <a href="#sale" className="btn btn-primary">Shop the sale <Icon name="arrow" size={16}/></a>
        </div>
      </article>
      <div className="deal-side">
        <article className="deal-card purple" aria-labelledby="bundle-title">
          <div>
            <p className="small-eyebrow">Bundle &amp; save</p>
            <h4 id="bundle-title">Build your capsule, save 15%</h4>
            <p>Mix any 3 essentials and we'll take 15% off automatically at checkout.</p>
          </div>
          <a href="#bundle" className="shop-link">Start a bundle →</a>
        </article>
        <article className="deal-card green" aria-labelledby="member-title">
          <div>
            <p className="small-eyebrow">Members only</p>
            <h4 id="member-title">Early access: Fall drop</h4>
            <p>Join free and shop new arrivals 48 hours before everyone else.</p>
          </div>
          <a href="#join" className="shop-link">Join the club →</a>
        </article>
      </div>
    </div>
  </section>
);

const Editorial = () => (
  <section className="block" aria-labelledby="ed-head">
    <div className="section-head">
      <div>
        <h2 id="ed-head">From the journal</h2>
        <p>Stories, guides, and the people behind the craft.</p>
      </div>
      <a href="#journal" className="section-link">Read all stories <Icon name="arrow" size={14}/></a>
    </div>
    <div className="editorial">
      {ARTICLES.map(a => (
        <article key={a.id} className="article-card" aria-labelledby={`a-${a.id}`}>
          <div className={`article-media ${a.media}`} aria-hidden="true">
            <span className="article-tag">{a.tag}</span>
          </div>
          <div className="article-body">
            <span className="article-meta">{a.meta}</span>
            <h3 id={`a-${a.id}`}><a href={`#article-${a.id}`}>{a.title}</a></h3>
            <p>{a.excerpt}</p>
          </div>
        </article>
      ))}
    </div>
  </section>
);

const Newsletter = () => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const inputRef = useRef(null);

  const onSubmit = (e) => {
    e.preventDefault();
    const trimmed = email.trim();
    if (!trimmed || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
      setError("Please enter a valid email address (e.g. you@example.com).");
      setSubmitted(false);
      inputRef.current?.focus();
      return;
    }
    setError("");
    setSubmitted(true);
    setEmail("");
  };

  return (
    <section className="newsletter container" aria-labelledby="nl-head">
      <div>
        <h2 id="nl-head">Get 10% off your first order</h2>
        <p>Join the Northform list for early access, restocks, and the occasional good story. No spam, ever.</p>
      </div>
      <form className="newsletter-form" noValidate onSubmit={onSubmit} aria-describedby="nl-help">
        <label htmlFor="nl-email" style={{ fontSize: "0.9rem", color: "var(--text-muted)" }}>
          Email address <span style={{ color: "var(--accent-strong)" }} aria-hidden="true">*</span>
        </label>
        <div className="newsletter-row">
          <input
            ref={inputRef}
            id="nl-email"
            type="email"
            required
            aria-required="true"
            aria-invalid={!!error}
            aria-describedby={error ? "nl-error nl-help" : "nl-help"}
            placeholder="you@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <button type="submit" className="btn btn-primary">Subscribe</button>
        </div>
        {error && <p id="nl-error" className="error" role="alert">{error}</p>}
        <p id="nl-help" className="help">By subscribing you agree to our <a href="#privacy" style={{ color: "var(--accent-strong)" }}>privacy policy</a>. Unsubscribe anytime.</p>
        <div role="status" aria-live="polite" className="success">
          {submitted && "Thanks — check your inbox to confirm and grab your 10% code."}
        </div>
      </form>
    </section>
  );
};

const Footer = () => (
  <footer className="site-footer" aria-labelledby="footer-head">
    <h2 id="footer-head" style={{ position: "absolute", left: -9999 }}>Site footer</h2>
    <div className="container">
      <div className="footer-grid">
        <div className="footer-brand">
          <div className="brand" style={{ marginBottom: 12 }}>
