// ---------- App ----------
const App = () => {
  const [cart, setCart] = useState(0);
  const [wishlist, setWishlist] = useState(() => new Set());
  const [announce, setAnnounce] = useState("");

  const addToCart = useCallback((id) => {
    setCart(c => c + 1);
    const product = PRODUCTS.find(p => p.id === id);
    setAnnounce(`${product?.name || "Item"} added to cart.`);
  }, []);

  const toggleWishlist = useCallback((id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      const product = PRODUCTS.find(p => p.id === id);
      if (next.has(id)) {
        next.delete(id);
        setAnnounce(`${product?.name || "Item"} removed from wishlist.`);
      } else {
        next.add(id);
        setAnnounce(`${product?.name || "Item"} added to wishlist.`);
      }
      return next;
    });
  }, []);

  return (
    <>
      <a href="#main" className="skip-link">Skip to main content</a>
      <TopBar />
      <Header cartCount={cart} wishlistCount={wishlist.size} />
      <main id="main" className="container" tabIndex="-1">
        <Hero />
        <ValueProps />
        <Categories />
        <FeaturedProducts wishlist={wishlist} onWishlist={toggleWishlist} onAdd={addToCart} />
        <Deals />
        <Editorial />
      </main>
      <Newsletter />
      <Footer />
      <div role="status" aria-live="polite" style={{ position: "absolute", left: -9999, width: 1, height: 1, overflow: "hidden" }}>
        {announce}
      </div>
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
